const std = @import("std");
const fma = @import("src/scalar_fma.zig");
comptime { _ = fma; }
extern fn probe_fma32(a: u32, b: u32, c: u32) callconv(.c) u32;
extern fn probe_fma64(a: u64, b: u64, c: u64) callconv(.c) u64;
extern fn probe_constant_nan() callconv(.c) u64;
export fn probe_zig_nan() callconv(.c) f64 { return @bitCast(@as(u64, 0x7ff8_0000_0000_0000)); }
export fn probe_zig_div(a: f64, b: f64) callconv(.c) f64 { return a / b; }

pub fn main(init: std.process.Init) !void {
    var cases = [_][3]u32{
        .{ 0x3f800800, 0x3f800800, 0x0d800000 },
        .{ 0x3f000000, 0x40000000, 0xbf800000 },
        .{ 0x3f400000, 0x3e800000, 0xbe800000 },
        .{ 0x80000001, 0x3f000000, 0x00000001 },
    };
    var wide = [_][3]u64{
        .{ 0x7fefffffffffffff, 0x4000000000000000, 0xffefffffffffffff },
        .{ 0x3ff0000002000000, 0x3ff0000004000000, 1 },
        .{ 0x3ff0000000000001, 0x3feffffffffffffe, 0xbff0000000000000 },
    };
    var max: f64 = @bitCast(@as(u64, 0x7fefffffffffffff));
    std.mem.doNotOptimizeAway(&cases);
    std.mem.doNotOptimizeAway(&wide);
    std.mem.doNotOptimizeAway(&max);
    var buffer: [1024]u8 = undefined;
    var stdout: std.Io.File.Writer = .init(.stdout(), init.io, &buffer);
    for (cases, 0..) |args, i| {
        const direct: u32 = @bitCast(fma.fma(@bitCast(args[0]), @bitCast(args[1]), @bitCast(args[2])));
        try stdout.interface.print("f32 case {d}: Zig=0x{x}, C=0x{x}\n", .{ i, direct, probe_fma32(args[0], args[1], args[2]) });
    }
    for (wide, 0..) |args, i| {
        const direct: u64 = @bitCast(fma.fma64(@bitCast(args[0]), @bitCast(args[1]), @bitCast(args[2])));
        try stdout.interface.print("f64 case {d}: Zig=0x{x}, C=0x{x}\n", .{ i, direct, probe_fma64(args[0], args[1], args[2]) });
    }
    const quotient_bits: u64 = @bitCast(probe_zig_div(1.0, max));
    try stdout.interface.print("constant NaN through C=0x{x}; reciprocal max=0x{x}\n", .{ probe_constant_nan(), quotient_bits });
    try stdout.interface.flush();
}

