#include <stdint.h>
extern float zmath_core_fmaf_soft(float, float, float);
extern double zmath_core_fma_soft(double, double, double);
extern double probe_zig_nan(void);
uint32_t probe_fma32(uint32_t a, uint32_t b, uint32_t c) {
  union { uint32_t u; float f; } aa = {.u=a}, bb = {.u=b}, cc = {.u=c}, result;
  result.f = zmath_core_fmaf_soft(aa.f, bb.f, cc.f);
  return result.u;
}
uint64_t probe_fma64(uint64_t a, uint64_t b, uint64_t c) {
  union { uint64_t u; double f; } aa = {.u=a}, bb = {.u=b}, cc = {.u=c}, result;
  result.f = zmath_core_fma_soft(aa.f, bb.f, cc.f);
  return result.u;
}
uint64_t probe_constant_nan(void) {
  union { uint64_t u; double f; } result = {.f=probe_zig_nan()};
  return result.u;
}
